import heapq
from collections import defaultdict


def propagation_delay(n: int, links: list[tuple[int, int, int]], source: int) -> int:
    graph: dict[int, list[tuple[int, int]]] = defaultdict(list)
    for a, b, ms in links:
        graph[a].append((b, ms))
    best = [None] * n
    best[source] = 0
    heap = [(0, source)]
    while heap:
        time, node = heapq.heappop(heap)
        if time > best[node]:
            continue
        for nxt, ms in graph[node]:
            arrival = time + ms
            if best[nxt] is None or arrival < best[nxt]:
                best[nxt] = arrival
                heapq.heappush(heap, (arrival, nxt))
    return -1 if any(t is None for t in best) else max(best)
